export function searchConusDest(query: string): PerDiemDestination[] {
  if (!query.trim()) return CONUS_DESTINATIONS;
  const q = query.toLowerCase();
  return CONUS_DESTINATIONS.filter(d =>
    d.city.toLowerCase().includes(q) ||
    d.state.toLowerCase().includes(q) ||
    d.county.toLowerCase().includes(q),
  );
}